package za.co.bacy.admin;
import android.app.*;import android.app.job.*;import android.content.*;import android.net.*;import android.os.*;import org.json.JSONObject;import java.io.*;import java.net.URL;import java.nio.charset.StandardCharsets;import java.util.UUID;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import javax.net.ssl.HttpsURLConnection;import za.co.bacy.ui.ApkUpdates;
/** Administrator downloads never apply device-owner policies, lock-task or phone restrictions. */
final class AdminUpdates {
 static final String CHANGED="za.co.bacy.admin.UPDATE_CHANGED";private static final AtomicBoolean RUNNING=new AtomicBoolean();private static final ExecutorService WORKER=Executors.newSingleThreadExecutor();private static long lastCheck;
 static boolean wifi(Context c){ConnectivityManager m=c.getSystemService(ConnectivityManager.class);NetworkCapabilities n=m.getNetworkCapabilities(m.getActiveNetwork());return n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)&&n.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)&&!m.isActiveNetworkMetered();}
 static void schedule(Context c){c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(407,new ComponentName(c,AdminUpdateJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED).setPeriodic(15*60*1000L).setPersisted(true).build());}
 static void check(Context c,boolean manual){Context app=c.getApplicationContext();if(!manual&&!wifi(app))return;synchronized(AdminUpdates.class){long now=SystemClock.elapsedRealtime();if(!manual&&lastCheck>0&&now-lastCheck<60000)return;lastCheck=now;}WORKER.execute(()->run(app));}
 static boolean run(Context c){if(!RUNNING.compareAndSet(false,true))return false;try{perform(c);return false;}catch(Exception e){status(c,"failed","Update unavailable. Keep using the installed app; retry when online.",0);return true;}finally{RUNNING.set(false);}}
 static void status(Context c,String state,String message,int progress){c.getSharedPreferences("admin.updates",0).edit().putString("stage",state).putString("status",message).putInt("progress",progress).apply();c.sendBroadcast(new Intent(CHANGED).setPackage(c.getPackageName()));if(state.equals("ready")){NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("admin-updates","App updates",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent p=PendingIntent.getActivity(c,407,new Intent(c,MainActivity.class).putExtra("open_updates",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED)nm.notify(407,new Notification.Builder(c,"admin-updates").setSmallIcon(android.R.drawable.stat_sys_download_done).setContentTitle("Loop Secure Admin update ready").setContentText("Tap to review and install. Your phone stays available.").setContentIntent(p).setOnlyAlertOnce(true).setAutoCancel(true).build());}}
 static String describe(Context c){var p=c.getSharedPreferences("admin.updates",0);return "Version "+BuildConfig.VERSION_NAME+" · Automatic downloads on unmetered Wi-Fi.\n"+p.getString("status","Checks on Wi-Fi and through Android background scheduling.")+"\nThe admin app never restricts this phone. Android may ask you to approve installation.";}
 static JSONObject manifest(Context c,JSONObject envelope)throws Exception {var p=c.getSharedPreferences("admin.updates",0);JSONObject m=ApkUpdates.decode(envelope,ApkUpdates.PUBLIC_KEY);ApkUpdates.validate(m,p.getString("installation_id",""),"admin_update",c.getPackageName(),"admin",System.currentTimeMillis()/1000,BuildConfig.VERSION_CODE);if(m.optBoolean("required"))throw new SecurityException("Admin update cannot require a phone restriction");return m;}
 private static void perform(Context c)throws Exception {String token=new Store(c).get("access_token");if(token.isEmpty())return;var prefs=c.getSharedPreferences("admin.updates",0);String id=prefs.getString("installation_id","");if(id.isEmpty()){id=UUID.randomUUID().toString();prefs.edit().putString("installation_id",id).commit();}status(c,"checking","Checking the server for an update…",0);HttpsURLConnection h=(HttpsURLConnection)new URL(ApkUpdates.SERVER+"/api/admin/mobile/app-update").openConnection();h.setInstanceFollowRedirects(false);h.setConnectTimeout(12000);h.setReadTimeout(20000);h.setRequestMethod("POST");h.setRequestProperty("Content-Type","application/json");h.setRequestProperty("Authorization","Bearer "+token);h.setDoOutput(true);JSONObject envelope;try{try(OutputStream out=h.getOutputStream()){out.write(new JSONObject().put("version_code",BuildConfig.VERSION_CODE).put("installation_id",id).toString().getBytes(StandardCharsets.UTF_8));}if(h.getResponseCode()!=200)throw new IOException("Server update check unavailable");try(InputStream in=h.getInputStream()){envelope=new JSONObject(new String(za.co.bacy.ui.BoundedInput.read(in,20000),StandardCharsets.UTF_8));}}finally{h.disconnect();}if(!token.equals(new Store(c).get("access_token")))return;JSONObject m=manifest(c,envelope);if(!m.optBoolean("available")){prefs.edit().remove("manifest").apply();status(c,"current","Your administrator app is up to date.",100);c.getSystemService(NotificationManager.class).cancel(407);return;}File target=new File(c.getFilesDir(),"updates/admin.apk");boolean valid=false;if(target.exists())try{ApkUpdates.verifyFile(c,target,m);valid=true;}catch(Exception ignored){}if(!valid){status(c,"downloading","Downloading the administrator update…",0);ApkUpdates.download(c,m,target,n->status(c,"downloading","Downloading update… "+n+"%",n));}if(!token.equals(new Store(c).get("access_token")))return;prefs.edit().putString("manifest",envelope.toString()).apply();status(c,"ready","Update downloaded and verified. Tap Install update.",100);}
 static void install(Activity a){try{if(!a.getPackageManager().canRequestPackageInstalls()){a.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));return;}JSONObject m=manifest(a,new JSONObject(a.getSharedPreferences("admin.updates",0).getString("manifest","{}")));File apk=new File(a.getFilesDir(),"updates/admin.apk");ApkUpdates.verifyFile(a,apk,m);Uri uri=androidx.core.content.FileProvider.getUriForFile(a,a.getPackageName()+".updates",apk);a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){status(a,"failed","Check for the latest update again before installing. Your current app is retained.",0);check(a,true);}}
}
